function [yout] = alg_eq(x,u)
V=3.14     ;
U=642.18   ;
A=25.1     ;
k1=1.287e12;
k2=1.287e12;
k3=9.043e9 ;
E1=9758.3  ;
E2=9758.3  ;
E3=8560    ;
dH1=4200   ;
dH2=-11000 ;
dH3=-41850 ;
ro=1000    ;
cp=2.8121  ;
caf=5.5    ;
cbf=0      ;
ccf=0      ;
cdf=0      ;
tf=378     ;


y(1)=(V/u(1)                                );

y(2)=(U*A*( x(5) - u(2) )                   );

y(3)=(k1*exp( -E1/x(5) )                    );

y(4)=(k2*exp( -E2/x(5) )                    );

y(5)=(k3*exp( -E3/x(5) )                    );

y(6)=(-( dH1*y(3) + dH2*y(4) + dH3*y(5) )*V );

yout=y;
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
